"use client";

/** Generated by the NeuralCommons App Generator (layer: frontend). */

import { useEffect, useMemo, useState } from "react";
import { API } from "../../lib/api";

export default function Instruments() {
  const [rows, setRows] = useState([]);
  const [error, setError] = useState(null);
  const [query, setQuery] = useState("");
  const [trust, setTrust] = useState("");

  useEffect(() => {
    fetch(`${API}/instruments`, { cache: "no-store" })
      .then((response) => (response.ok ? response.json() : Promise.reject(new Error(`HTTP ${response.status}`))))
      .then((data) => setRows(data.instruments))
      .catch(() => setError("API unreachable"));
  }, []);

  const trusts = useMemo(() => [...new Set(rows.map((row) => row.trust))], [rows]);
  const visible = rows.filter((row) => {
    const matchesTrust = trust ? row.trust === trust : true;
    const matchesQuery = query ? JSON.stringify(row.payload || {}).toLowerCase().includes(query.toLowerCase()) : true;
    return matchesTrust && matchesQuery;
  });

  return (
    <main>
      <section className="panel">
        <h2>Instruments</h2>
        <p>
          <label>
            Filter{" "}
            <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="payload text" />
          </label>{" "}
          <label>
            Trust{" "}
            <select value={trust} onChange={(event) => setTrust(event.target.value)}>
              <option value="">all</option>
              {trusts.map((name) => (
                <option key={name} value={name}>
                  {name}
                </option>
              ))}
            </select>
          </label>
        </p>
        {error ? <p className="muted">{error}</p> : null}
        {!error && visible.length === 0 ? <p className="muted">no instruments yet</p> : null}
        <ul className="plain">
          {visible.map((row) => (
            <li key={row.cid}>
              <strong>{row.instrument}</strong> · {row.trust} · {row.created_at}
              <div className="mono muted">{row.cid}</div>
            </li>
          ))}
        </ul>
      </section>
    </main>
  );
}
